command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="108cedb5c17a1229604dc6f7a43fbc7c2eb775ab"
$candidate="fedac6118ab915e4f46974aa6519c9bffa3428df"
$branch="work/shell-provider-thumbnail-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider thumbnail baseline fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider thumbnail baseline"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider thumbnail baseline candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
& git diff --quiet $main $candidate -- app/winui src/base
if($LASTEXITCODE -ne 0){throw "baseline candidate unexpectedly changes product source"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider thumbnail baseline checkout failed"}
$exe=Join-Path $repo "out\winui\Release\flyExplorer.exe"
if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){throw "accepted Release runtime is missing"}
& python -X utf8 tests\winui\test_shell_provider_thumbnail_gui.py --configuration Release --capture before
if($LASTEXITCODE -ne 0){throw "provider thumbnail baseline GUI failed"}
$before=Join-Path $repo "logs\shell-provider-thumbnail\shell-provider-thumbnail-before.bmp"
if(-not(Test-Path -LiteralPath $before -PathType Leaf)){throw "provider thumbnail BEFORE missing"}
$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence|Out-Null
Copy-Item -LiteralPath $before -Destination (Join-Path $evidence "shell-provider-thumbnail-before.bmp") -Force
Write-Host ("SHELL_PROVIDER_THUMBNAIL_BASELINE_SHA256="+(Get-FileHash -Algorithm SHA256 $before).Hash.ToLowerInvariant())
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider thumbnail baseline"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider thumbnail baseline"}
Write-Host "SHELL_PROVIDER_THUMBNAIL_BASELINE=PASS"
